import React from 'react';

import PersonPlus from '@pohodnik/icons/svg/People/PersonPlus';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingJointlyEquipmentNameByType } from '@apps/Hiking/@helpers/jointlyEquipment.helper';
import { mapHikerToUser } from '@apps/Hiking/@mappers/hiking.mapper';
import {
  mapHikingJointlyEquipmentToAdd,
  mapHikingJointlyEquipmentToUpdate,
} from '@apps/Hiking/@mappers/hikingJointlyEquipment.mapper';
import {
  addHikingJointlyEquipment,
  addHikingJointlyEquipmentMember,
  deleteHikingJointlyEquipment,
  deleteHikingJointlyEquipmentMember,
  editHikingJointlyEquipment,
  getHikingJointlyEquipments,
} from '@apps/Hiking/@services/hikingJointlyEquipment.service';
import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingJointlyEquipmentType } from '@apps/Hiking/@types/DTO/hikingJointlyEquipment.dto.types';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohButton from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import HikingJointlyEquipmentCard from './HikingJointlyEquipmentCard';
import { editHikingJointlyEquipmentFormInModal } from './HikingJointlyEquipmentForm';

interface IHikingJointlyEquipmentListProps {
  id_hiking: number;
  type: HikingJointlyEquipmentType;
}

const HikingJointlyEquipmentList = ({ type, id_hiking }: IHikingJointlyEquipmentListProps) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [data, setData] = React.useState<IHikingJointlyEquipment[]>([]);

  const [canEditOwn, setCanEditOwn] = React.useState(false);
  const [canEditSome, setCanEditSome] = React.useState(false);

  const authContext = React.useContext(AuthContext);
  const hikingData = React.useContext(HikingContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hdt = await getHikingJointlyEquipments(id_hiking, type);
        setData(hdt);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        setCanEditOwn(accessGroup !== HikingAccessGroup.Readonly);
        setCanEditSome(
          [HikingAccessGroup.Full, HikingAccessGroup.All, HikingAccessGroup.Boss].includes(
            accessGroup,
          ),
        );
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking, type]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData || !authContext.user) {
    return <PohAlert variant={AlertVariant.Danger}>no hikingData</PohAlert>;
  }

  return (
    <>
      <PageHeader
        title={`${getHikingJointlyEquipmentNameByType(type)} похода «${hikingData.name}»`}
      >
        {canEditOwn && (
          <PohButton
            onClick={async () => {
              try {
                const up = await editHikingJointlyEquipmentFormInModal({
                  id: 0,
                  author: authContext.user!,
                  comment: '',
                  type: type,
                  created_at: new Date(),
                  equip: null,
                  members: [],
                  name: '',
                  updated_at: null,
                  capacity: 1,
                  capacity_max: 2,
                });
                const id = await addHikingJointlyEquipment(
                  mapHikingJointlyEquipmentToAdd(id_hiking, up),
                );
                notificationHelper.success('Сохранено');
                setData((a) => [...a, { ...up, id }]);
              } catch (error) {
                notificationHelper.error((error as Error)?.message);
              }
            }}
          >
            Добавить {getHikingJointlyEquipmentNameByType(type, 1, true).toLowerCase()}
          </PohButton>
        )}
      </PageHeader>

      <PohRow>
        {!data.length && (
          <Empty
            icon={
              type === 'watercraft' ? (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 100 50"
                  stroke="currentColor"
                  fill="none"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M5,25 C10,15 30,10 50,10 C70,10 90,15 95,25 C90,35 70,40 50,40 C30,40 10,35 5,25 Z" />

                  <ellipse cx="50" cy="25" rx="12" ry="6" />

                  <line x1="10" y1="10" x2="30" y2="22" />

                  <line x1="70" y1="22" x2="90" y2="10" />
                </svg>
              ) : (
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 100 100"
                  stroke="currentColor"
                  fill="none"
                  strokeWidth="4"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <polygon points="10,85 50,15 90,85" />
                  <line x1="50" y1="15" x2="50" y2="85" />

                  <line x1="10" y1="85" x2="90" y2="85" />
                </svg>
              )
            }
          >
            Нет {getHikingJointlyEquipmentNameByType(type, 5, true).toLowerCase()}
          </Empty>
        )}
        {data.map((jointlyEquipment) => {
          const isOwn = jointlyEquipment.author.id === authContext.user?.id;
          return (
            <PohCol sm={6} md={4} lg={3} key={jointlyEquipment.id}>
              <HikingJointlyEquipmentCard
                jointlyEquipment={jointlyEquipment}
                key={jointlyEquipment.id}
                toolbar={
                  canEditSome || (canEditOwn && isOwn) ? (
                    <footer className="d-flex">
                      <PohButton
                        icon={IconsEnum.edit}
                        onClick={async () => {
                          try {
                            const up =
                              await editHikingJointlyEquipmentFormInModal(jointlyEquipment);
                            await editHikingJointlyEquipment(
                              mapHikingJointlyEquipmentToUpdate(id_hiking, up),
                            );
                            notificationHelper.success('Сохранено');
                            setData((a) => a.map((b) => (b.id == up.id ? up : b)));
                          } catch (error) {
                            notificationHelper.error((error as Error)?.message);
                          }
                        }}
                      />
                      <PohButton
                        icon={IconsEnum.trash}
                        onClick={async () => {
                          try {
                            const up = await deleteHikingJointlyEquipment({
                              id_hiking,
                              id: jointlyEquipment.id,
                            });
                            notificationHelper.success('Удалено');

                            up && setData((a) => a.filter((b) => b.id !== jointlyEquipment.id));
                          } catch (error) {
                            notificationHelper.error((error as Error)?.message);
                          }
                        }}
                      />

                      <PohButton
                        icon
                        onClick={async (e) => {
                          try {
                            if (jointlyEquipment.members.length >= jointlyEquipment.capacity_max) {
                              notificationHelper.warn('Полна коробочка');
                              return false;
                            }
                            const hiker = await selectHikerAsync(id_hiking);
                            const comment = e.metaKey || e.altKey ? (prompt('comment') ?? '') : '';
                            const id = await addHikingJointlyEquipmentMember({
                              id_hiking,
                              id_hiking_jointly_equipment: jointlyEquipment.id,
                              id_user: hiker.idUser,
                              comment,
                              date_from: null,
                              date_to: null,
                            });
                            notificationHelper.success('Сохранено');
                            setData((a) =>
                              a.map((b) =>
                                b.id == jointlyEquipment.id
                                  ? {
                                      ...jointlyEquipment,
                                      members: [
                                        ...jointlyEquipment.members,
                                        {
                                          id,
                                          comment,
                                          created_at: new Date(),
                                          id_author: hiker.idUser,
                                          date_from: null,
                                          date_to: null,
                                          user: mapHikerToUser(hiker),
                                        },
                                      ],
                                    }
                                  : b,
                              ),
                            );
                          } catch (error) {
                            notificationHelper.error((error as Error)?.message);
                          }
                        }}
                        className="ms-auto"
                      >
                        <PersonPlus />
                      </PohButton>
                    </footer>
                  ) : undefined
                }
              >
                <PohList
                  flush
                  data={jointlyEquipment.members.map((u) => {
                    return {
                      key: u.id,
                      className: 'p-1',
                      children: (
                        <div className="d-flex align-items-center">
                          <PohAva
                            src={u.user.photo}
                            alt={u.user.name + ' ' + u.user.surname}
                            className="me-2"
                          />
                          <div className="me-2">
                            <strong className="text-truncate text-nowrap d-block">
                              {u.user.name + ' ' + u.user.surname}
                            </strong>
                            {u.comment.length > 0 && (
                              <small>
                                <em>
                                  <small>{u.comment}</small>
                                </em>
                              </small>
                            )}
                          </div>
                          {(canEditSome || (canEditOwn && isOwn)) && (
                            <PohButton
                              className="ms-auto"
                              icon={IconsEnum.trash}
                              onClick={async () => {
                                try {
                                  await deleteHikingJointlyEquipmentMember({ id: u.id, id_hiking });
                                  notificationHelper.success('Удалено');
                                  setData((a) =>
                                    a.map((b) =>
                                      b.id == jointlyEquipment.id
                                        ? {
                                            ...jointlyEquipment,
                                            members: jointlyEquipment.members.filter(
                                              (v) => v.id !== u.id,
                                            ),
                                          }
                                        : b,
                                    ),
                                  );
                                } catch (error) {
                                  notificationHelper.error((error as Error)?.message);
                                }
                              }}
                            />
                          )}
                        </div>
                      ),
                    };
                  })}
                />
              </HikingJointlyEquipmentCard>
            </PohCol>
          );
        })}
      </PohRow>
    </>
  );
};

export default HikingJointlyEquipmentList;
