import React from 'react';

import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

import { HikingContext } from '../@contexts/hikingContext';
import { getHikingJointlyEquipmentNameByType } from '../@helpers/jointlyEquipment.helper';
import { getHikingDataAsync } from '../@services/hiking.service';
import HikingJointlyEquipmentList from './components/HikingJointlyEquipmentList';
import { HikingJointlyEquipmentType } from '../@types/DTO/hikingJointlyEquipment.dto.types';
import { IHikingData } from '../@types/hiking.types';

interface IHikingJointlyEquipmentsProps {
  id_hiking: number;
  type: HikingJointlyEquipmentType;
}

const HikingJointlyEquipments: React.FC<IHikingJointlyEquipmentsProps> = ({ id_hiking, type }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [hikingData, setHikingData] = React.useState<IHikingData>();

  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData || !authContext.user) {
    return <PohAlert variant={AlertVariant.Danger}>no hikingData</PohAlert>;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          {
            href: `/hiking/${id_hiking}/jointlyEquipments`,
            text: getHikingJointlyEquipmentNameByType(type),
            active: true,
          },
        ]}
      />
      <HikingContext.Provider value={hikingData}>
        <HikingJointlyEquipmentList id_hiking={id_hiking} type={type} />
      </HikingContext.Provider>
    </PohContainer>
  );
};

export default HikingJointlyEquipments;
